entries[218118] = { ["name"] = "Lukous Maske der Regeneration", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
