entries[218120] = { ["name"] = "Arsenal: Waffen des Friedensbewahrers der Exodar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der Dunkeleisenwaffen." }
entries[218121] = { ["name"] = "Kerzenlicht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Von Euch geht eine schwache Flamme aus. Die Dunkelheit vermag sie nicht zu vertreiben, aber sie offenbart 5 Min. lang durch die Dunkelheit verborgene Geheimnisse.\n\nSolange das Licht scheint, könnt Ihr nicht in Verstohlenheit übergehen.\n\"Ihr habt die Kerze tatsächlich genommen.\"\nVerkaufspreis:" }
entries[218122] = { ["name"] = "Gestohlenes Relikt", ["text"] = "\"Das Licht in diesem Relikt leuchtet immer noch, trotz der Versuche der Kobyss, es zu verderben.\"" }
entries[218123] = { ["name"] = "Leuchtender Splitter", ["text"] = "\"Ihr konntet den Schmutz abfegen, der verwendet wurde, um das Leuchten dieses Splitters zu verdunkeln.\"" }
entries[218124] = { ["name"] = "Elementextraktor", ["text"] = "Questgegenstand\nBenutzen: Entzieht Elementaren Elementarenergie, um einzigartige Kräfte zu erhalten. (5 Sek. Abklingzeit)\n\"Ein Gerät, das unerschütterliche Kräfte von Elementaren aufspürt und sie ihnen entzieht.\"" }
entries[218125] = { ["name"] = "Reaktiver eingewebter Wappenschild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchildhand Schild\n2442 Rüstung\n+128 Stärke\n+394 Intelligenz\n43 Rüstung\nHaltbarkeit 120 / 120\nAnlegen: Beim Erleiden von Magieschaden besteht eine Chance, dass die Spinnweben reagieren und sich anpassen, wodurch sie Euch für 30 Sek. Sek. mit Schutzfäden einwickeln. Solange die Schutzfäden aktiv sind, absorbieren sie sämtlichen Schaden, den Ihr durch Zauber dieser Quelle erleiden würdet, bis zu 81103 Schaden. (2 Min. Abklingzeit) (2Min. Abklingzeit)\nVerkaufspreis:" }
entries[218126] = { ["name"] = "Spritze des Besudlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nZweihändig Stangenwaffe\n487 - 905 Schaden Geschwindigkeit 3.60\n(193.3 Schaden pro Sekunde)\n+416 Ausdauer\nErhöht Eure Tempowertung um + 478.\nHaltbarkeit 120 / 120\nAnlegen: Eure Nahkampfangriffe und -fähigkeiten haben eine Chance, das Blut Eures Gegners zu besudeln und im Verlauf von 10 Sek. [Quellwert] Naturschaden zu verursachen. Weitere Injektionen überschneiden sich.\n\nWenn ein von 'Besudeltes Blut' betroffenes Ziel stirbt, wird das verbleibende Gift entzogen und in die Klinge zurückgeführt, wodurch Eure nächsten Nahkampffähigkeiten ( 1 * 8083 ) zusätzlichen Naturschaden verursachen.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[218127] = { ["name"] = "Immerblühender Pilz", ["text"] = "Questgegenstand\n\"Dieser Pilz wächst schnell und scheint auf allem zu sprießen.\"" }
entries[218128] = { ["name"] = "Drakonisches Banner der Aspekte", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt ein Banner auf, das Eure Erfolge im Kampf gegen die Drachen zur Schau stellt. (10 Min Abklingzeit)" }
entries[218129] = { ["name"] = "Pfeilspitzengötze aus Porzellan", ["text"] = "Wird beim Aufheben gebunden" }
entries[218130] = { ["name"] = "Schließkiste des Abenteurers", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Ausrüstung für andere Klassenspezialisierungen.\"\n<Zum Öffnen rechtsklicken>" }
entries[218131] = { ["name"] = "Perfekte Peitschenpilzkappe", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Peitschenpilzkappe ist die perfekte Mischung! Sie ist feucht-matschig, saugfähig und robust genug, um die felsigen Ebenen eines moosbedeckten Irdenen zu liebkosen.\"" }
entries[218187] = { ["name"] = "Ätzblüte", ["text"] = "Questgegenstand\n\"Aus den Blüten dieser orangefarbenen Pflanze lässt sich mit Wasser ein ätzendes Lösungsmittel herstellen.\"" }
