entries[218739] = { ["name"] = "Makelloses Horn", ["text"] = "Questgegenstand\n80 ( 80)\n\"Anhand der Ringe an diesem Horn lässt sich das Alter des Einhornelches ablesen. Es ist glatt und beständig und wird zu einem wunderschönen, hochwertigen Instrument werden.\"" }
entries[218740] = { ["name"] = "Aschenbruch", ["text"] = "Questgegenstand\n80 ( 80)\n\"Eine leichte Schicht grauer Pollen bedeckt diese Blumen. Schon vom kleinsten Windhauch werden die Pollen in die Luft gehoben, wodurch es aussieht, als würde Asche vom Himmel regnen.\"" }
