entries[219002] = { ["name"] = "Köder für Spiegelregenbogenfische", ["text"] = "Benutzen: Erhöht 30 Min. lang die Chance, Spiegelregenbogenfische zu fangen.\nVerkaufspreis:" }
entries[219003] = { ["name"] = "Köder für stille Flussbarsche", ["text"] = "Benutzen: Erhöht 30 Min. lang die Chance, stille Flussbarsche zu fangen.\nVerkaufspreis:" }
entries[219004] = { ["name"] = "Köder für dornische Hechte", ["text"] = "Benutzen: Erhöht 30 Min. lang die Chance, dornische Hechte zu fangen.\nVerkaufspreis:" }
entries[219005] = { ["name"] = "Köder für Arathorhammerfische", ["text"] = "Benutzen: Erhöht 30 Min. lang die Chance, Arathorhammerfische zu fangen.\nVerkaufspreis:" }
entries[219006] = { ["name"] = "Köder für tosende Anglersucher", ["text"] = "Benutzen: Taucht Euren Haken in Anglersucherköder, der einen Fang aus jedem Fischschwarm in den Schallenden Tiefen oder Heilsturz garantiert.\n\nDieser Köder hält 30 Min. lang an und lässt sich bis zu 50-mal stapeln.\nVerkaufspreis:" }
entries[219007] = { ["name"] = "Köder für scheue Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\nBenötigt Kürschnerei von Khaz Algar (1)\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken.\"\nVerkaufspreis:" }
entries[219008] = { ["name"] = "Überragender Wildtierköder", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder und lockt eine hochkarätige scheue Kreatur aus ihrem Versteck.\n\nKann nur in der Grollenden Einöde in den Schallenden Tiefen eingesetzt werden.\nBenötigt Kürschnerei von Khaz Algar (1)\n\"Ein exquisiter Köder, der nach detaillierten Vorgaben hergestellt wurde, um ein mächtiges Wildtier anzulocken.\"\nVerkaufspreis:" }
entries[219009] = { ["name"] = "Köder für kristalline Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit Kristallpulver angereichert.\"\nVerkaufspreis:" }
entries[219010] = { ["name"] = "Köder für zuckende Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit einer Essenz angereichert, die vor boshafter Energie trieft.\"\nVerkaufspreis:" }
entries[219011] = { ["name"] = "Köder für sporenverschmolzene Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit magischen Sporen angereichert.\"\nVerkaufspreis:" }
entries[219013] = { ["name"] = "Vortrefflicher Bestienreißzahn", ["text"] = "Handwerksmaterial\n\"Ein riesiger Reißzahn einer besonders mächtigen, aber scheuen Kreatur in Khaz Algar, der von Kürschnern gewonnen wurde. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[219014] = { ["name"] = "Rachsüchtiger Feuergeist", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 493.\nAnlegen: Eure Distanzangriffe haben eine Chance, eine rachsüchtige Flamme zu Eurem Ziel zu schicken, die ( 1 * 19916 ) Feuerschaden verursacht, wenn sie dieses erreicht.\n\nDer Geist wächst, während er sich auf das Ziel zubewegt, und verursacht bis zu 100% zusätzlichen Feuerschaden.\nVerkaufspreis:" }
entries[219015] = { ["name"] = "Edelstein von Ausgazur", ["text"] = "Questgegenstand\n\"Dieser perfekte Edelstein glitzert leicht in der Sonne. Man könnte ihn auf ewig anschauen.\"" }
entries[219016] = { ["name"] = "Beschichtete Stahlspitzen", ["text"] = "Questgegenstand" }
entries[219017] = { ["name"] = "Silberne Rüstungsschnallen", ["text"] = "Questgegenstand" }
entries[219018] = { ["name"] = "Hochverehrtes Emblem der Irdenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+389 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, jene um Euch zu ermutigen und 924 Vielseitigkeit zu gewähren, die zwischen Euch und Verbündeten in der Nähe aufgeteilt wird.\n\nDie Vielseitigkeit wird für jeden betroffenen Verbündeten erhöht. Bis zu 5 Verbündete.\nVerkaufspreis:" }
entries[219019] = { ["name"] = "Wildtierlockduft", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet die Flasche, um einen Duft freizusetzen, der alle unbeschäftigten häutbaren Wildtiere innerhalb von 60 Metern sofort zu Euch lockt.\n\nKann nur im Freien in Khaz Algar verwendet werden. (5 Min Abklingzeit)\nBenötigt Kürschnerei von Khaz Algar (1)\nVerkaufspreis:" }
