entries[219191] = { ["name"] = "Hastig geschriebene Notizen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr ordnet 15 hastig dahingekritzelte Notizen zu etwas Verständlichem an.\nBenötigt Ingenieurskunst von Khaz Algar (1)\n\"Obwohl es Eure eigene Handschrift ist, sind die Worte fast unleserlich. Immerhin vermittelt Eure Skizze das Wesentliche.\"" }
entries[219192] = { ["name"] = "Verständlich geordnete Ideen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studiert Eure Notizen, um einen neuen Ingenieurskunstbauplan auszuwählen, den Ihr erlernen wollt.\n\nJe weiter Ihr Euch in der Ingenieurskunst spezialisiert, desto mehr Baupläne stehen dafür zur Verfügung.\nBenötigt Ingenieurskunst von Khaz Algar (1)\n\"Ihr seid nicht ganz sicher, was diese Fetzen darstellen sollten. Eine durchdachte Neuanordnung könnte neue Ideen hervorbringen.\"" }
entries[219194] = { ["name"] = "Magischer Mulch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine mittlere Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\nBenötigt Kräuterkunde von Khaz Algar (1)\nVerkaufspreis:" }
entries[219195] = { ["name"] = "Verzauberter Mulch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine große Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\nBenötigt Kräuterkunde von Khaz Algar (1)\nVerkaufspreis:" }
entries[219196] = { ["name"] = "Machterfüllter Mulch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bereitet den Mulch für dessen Verwendung vor. Bedeckt damit Eure nächsten Kräuter, die Ihr sammeln möchtet, um eine riesige Menge Finesse zu erhalten. Ihr könnt immer nur jeweils eine Portion Mulch verwenden.\nBenötigt Kräuterkunde von Khaz Algar (1)\nVerkaufspreis:" }
