entries[219283] = { ["name"] = "Obsidianiris", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wie der Schwarm, dem sie ihren Namen verdanken, gedeihen auch diese pechschwarzen Blumen unter rauen Bedingungen.\"" }
entries[219284] = { ["name"] = "Explosivstangen", ["text"] = "Questgegenstand\nBenutzen: Stuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 2 Sek..\nInflicts 4 Fire damage to enemies within 5 yards of the impact. (5 Sek. Abklingzeit)\n\"Dieser Sprengstoff ist für zwei Dinge gut: Koboldtunnel zum Einsturz bringen.\"" }
entries[219285] = { ["name"] = "Azurlilie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Selbst die Blütenblätter knistern vor arkaner Energie. Ihren Knospen sollen nur in Gegenwart großer Mengen Magie erblühen.\"" }
entries[219286] = { ["name"] = "Ver-tretbarer Schneekugelyeti", ["text"] = "Wird beim Aufheben gebunden\n\"Lernt, wie man ver-tretbare Schneekugelyetis beschwört.\"" }
entries[219287] = { ["name"] = "Zeitberührtes Gänseblümchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit feinem Bronzestaub bedeckt, funkeln und strahlen diese Gänseblümchen in der Mittagssonne.\"" }
entries[219288] = { ["name"] = "Viridianblume", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Blüten dieser Blume fühlen sich kühl an, als wären sie gerade erst in einem tiefen, dunklen Wald gepflückt worden.\"" }
entries[219289] = { ["name"] = "Ver-tretbarer winziger Schneemann", ["text"] = "Wird beim Aufheben gebunden\n\"Lernt, wie man ver-tretbare winzige Schneemänner beschwört.\"" }
entries[219290] = { ["name"] = "Rubinblüte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Warm und voller Leben strotzen diese Blumen nur so vor Pollen. Gut für Bienen, weniger für Nasen.\"" }
entries[219291] = { ["name"] = "Ver-tretbarer Babygriesgram", ["text"] = "Wird beim Aufheben gebunden\n\"Lernt, wie man ver-tretbare Babygiesgrame beschwört.\"" }
entries[219292] = { ["name"] = "Verblüffende Schmuggelware", ["text"] = "Questgegenstand\nEinzigartig (5)\n\"Samophlangteile - Nicht schütteln.\"" }
entries[219293] = { ["name"] = "Geheiminformationen der Sureki", ["text"] = "Questgegenstand\nEinzigartig (4)\n\"Dieses scheinbar leere Pergament sondert verschiedenste beißende Gerüche ab.\"" }
entries[219294] = { ["name"] = "Energiegeladene Sturmkrähenfeder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Beweglichkeit\nBenutzen: Hält die Feder für [1.0][1] Sek. hoch, um mit der Macht des Sturms zuzuschlagen, der auf den Zielort niedergeht und ( 1 * 124864 ) Naturschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219295] = { ["name"] = "Siegel der algarischen Einigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Fähigkeiten haben eine Chance, einen irdenen Verbündeten zu Hilfe zu rufen, der Euch im Kampf unterstützt. (15s Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219296] = { ["name"] = "Entropischer Skardynkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 604.\nAnlegen: Eure Zauber haben eine Chance, die Leerenenergie zu destabilisieren und ein verderbtes Fragment freizusetzen. Wenn Ihr ein Fragment aufnehmt, werdet Ihr kurzzeitig von seiner Macht durchdrungen, was Eure Intelligenz 15 Sek. lang um 1421 erhöht.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219297] = { ["name"] = "Glutbräukrug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Teilt gelegentlich ein Getränk mit Verbündeten, die Euch im Kampf beistehen, das ihnen 15 Sek. lang 700 ihres Primärwertes gewährt und 19079 Schaden absorbiert. Auch Ihr nehmt einen Schluck, der 377 Hauptwert gewährt und 97936 Schaden absorbiert.\n\nWenn Eure Gesundheit unter 50% fällt, nehmt Ihr einen Notfallschluck. Dies kann nur einmal alle 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\n\"Für den Konsum niederer Sterblicher verdünnt.\"\nVerkaufspreis:" }
entries[219298] = { ["name"] = "Gefräßiger Honigbrummer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\nBenutzen: Ruft einen unersättlichen Verbündeten herbei und reitet in den Sonnenuntergang (oder [Quellwert] Meter weit, wenn diese Strecke kürzer ist). Außerdem werden ( 1 * 149371 ) Feuerschaden zwischen allen Gegnern aufgeteilt, über die Ihr hinwegreitet. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[219299] = { ["name"] = "Synergetischer Gebräuterialisator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, das Gerät aufzuladen und ein Auffüllfass in die Nähe Eures Ziels anzufordern. Wenn das Fass beschädigt wird, explodiert es und verursacht ( 1 * 84121 ) Feuerschaden, die unter den Gegnern in der Nähe aufgeteilt werden.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219300] = { ["name"] = "Skarmoraksplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Stärke\nBenutzen: Haltet den Splitter fest umschlossen, um Euch mit kristalliner Energie anzureichern und Eure Meisterschaft für 15 Sek. um 2756 zu erhöhen. (1 Min, 30 Sek. Abklingzeit)\nAnlegen: Der Splitter zieht Restenergie von besiegten Gegnern an und erhöht Eure Meisterschaft für 15 Sek. um 58 , bis zu 5-mal.\nVerkaufspreis:" }
entries[219301] = { ["name"] = "Übertakteter Zahnradbumerangwerfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenutzen: Wirft den überhitzten Zahnradbumerang und fügt Gegnern ( 1 * 41390 ) Flammenschlagschaden zu, wobei er an Hitze verliert, während er sie durchschneidet. (2 Min Abklingzeit)\nAnlegen: Eure Nahkampfangriffe haben eine Chance, die Zahnräder der Schleuder per Kurbel aufzuziehen, was deren Abklingzeit um 5 Sek. verringert und Eure Waffe aufheizt, wodurch Euer nächster Angriff ( 1 * 23306 ) zusätzlichen Feuerschaden verursacht.\nVerkaufspreis:" }
entries[219302] = { ["name"] = "Symphonie des Schrottsängers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nAnlegen: Eure Heilfähigkeiten haben eine Chance, Metall in der Nähe dazu zu bringen, einen Schild um einen Verbündeten zu bilden, der 45216 Schaden absorbiert.\n\nDer Schild reagiert explosiv auf Feuer und fügt nahen Gegnern 4162 Feuerschaden zu, wenn er getroffen wird.\nVerkaufspreis:" }
entries[219303] = { ["name"] = "Zuwachs des Obersten Sprechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 604.\nBenutzen: Lädt den Kristall auf, um einen Spalt zu beschwören, der Gegnern in der Nähe Energie entzieht und im Verlauf von 6 Sek. ( 1 * 45046 * 6) Schattenschaden verursacht.\n\nWenn der Spalt kollabiert, kehrt die entzogene Energie zu Euch zurück, um Eure Intelligenz 20 Sek. lang um 135 zu erhöhen und für jeden getroffenen Gegnern weiter zu steigern. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[219304] = { ["name"] = "Wachspfeife des Wagenführers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, eine Koboldlore auf Euer Ziel zu lenken. Diese entsendet einen rasenden Trupp, der mit Gegnern zusammenstößt und ( 1 * 61010 ) körperlichen Schaden verursacht, die unter allen getroffenen Gegnern aufgeteilt werden.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\n\"Die symbolische Trophäe eines Helden, denn die Kobolde müssen nicht beschworen werden, die Kobolde verzehren sich nach den Katakomben.\"\nVerkaufspreis:" }
entries[219305] = { ["name"] = "Verziertes Lohenzarwachs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, das Wachs zu verzaubern, um für 15 Sek. eine lodernde Kerze zu erzeugen, die Eure Vielseitigkeit um 1292 und, während Ihr in ihrem Licht bleibt, weiter um 339 erhöht.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219306] = { ["name"] = "Stichel des Kerzenkönigs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nBenutzen: Schnitzt eine Wachskopie Eures Ziels, die 50% des erlittenen Schadens absorbiert. Durch die Absorption erhitzt sich das Wachs, bis es nach Absorption von 264398 Schaden schmilzt. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219307] = { ["name"] = "Fragment der Dunkelheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Eure Fähigkeiten haben eine Chance, die Dunkelheit zu Euch zu rufen, wodurch sich Eure Hauptwert um 281 erhöht, bis zu ( 281 * 5).\n\nBei Erreichen voller Kraft wird die Dunkelheit entfesselt und verursacht ( 1 * 35879 * 15 / 3) Schattenschaden, die zwischen Gegnern in der Nähe im Verlauf von 15 Sek. aufgeteilt werden, bevor sie wieder in das Fragment verblasst.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219308] = { ["name"] = "Siegel des Priorats", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhebt Euer Siegel zum Licht und erhöht so Euren höchsten Sekundärwert 20 Sek. lang um 2756 . Eure Tat inspiriert andere Siegelträger Eurer Gruppe in der Nähe und gewährt ihnen 20 Sek. lang 73 desselben Werts. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt das Priorat der Heiligen Flamme in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219309] = { ["name"] = "Foliant der Hingabe des Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Ihr blättert zu den 50 Versen der inneren Abhärtung weiter und lest sie, während Ihr angegriffen werdet.\n'Innere Abhärtung' erhöht Eure Rüstung um 1438 und gewährt Euren Angriffen eine Chance, einen Schutz zu beschwören, der 67723 Magieschaden absorbiert. Sobald Ihr fertig seid, blättert Ihr zum nächsten Kapitel weiter.\n\nGilt nur für Tankspezialisierungen. (500ms Abklingzeit)\nBenutzen: Blättert mit erhöhter Strahlung durch die Textstellen des Folianten. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt das Priorat der Heiligen Flamme in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219310] = { ["name"] = "Explodierender Lichtsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nBenutzen: Beschwört eine berstende Lichtbrut, die ihre Gesundheit opfert, um Lichtstöße zu entfesseln, die 57024 Heiligschaden verursachen, der alle 2 Sekunden auf Gegner in der Nähe aufgeteilt wird, solange die Brut lebt. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nSchließt das Priorat der Heiligen Flamme in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219311] = { ["name"] = "Leerenpaktstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Stärke\nAnlegen: Eure Angriffe haben eine Chance, den Pakt anzurufen und eine Explosion auszulösen, die ( 1 * 35361 ) Schattenschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden, und Euer Tempo 10 Sek. lang um 377 erhöht.\n\nEuer Tod beendet den Pakt und führt zu einer gewaltigen Explosion.\nSchließt die Morgenbringer in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219312] = { ["name"] = "Ermächtigender Kristall von Anub'ikkaj", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, eine wachsende Ermächtigung aus dem Kristall freizusetzen, die einen zufälligen Sekundärwert 20 Sek. lang um 1392 erhöht.\nSchließt die Morgenbringer in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219313] = { ["name"] = "Mereldars Tribut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nBenutzen: Entfesselt einen Tribut aus heiligem Licht auf das Ziel und fügt ihm ( 1 * 53941 ) Heiligschaden zu. Die nächsten 5 Verbündeten, die das Ziel angreifen, erhalten den 'Segen von Mereldar', was ihre Vielseitigkeit 10 Sek. lang um 658 erhöht. (1 Min, 30 Sek. Abklingzeit)\nSchließt die Morgenbringer in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219314] = { ["name"] = "Kokonbrut von Ara-Kara", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 604.\nAnlegen: Eure Fähigkeiten haben eine Chance, den Kokon zu bewegen, der ein Ei freigibt, das Eure Hauptwert um 213 erhöht. Jedes Ei schlüpft nach 1 Min. Die neue Brut greift Euer nächstes Ziel an und fügt ihm im Verlauf von 8 Sek. ( 1 * 1598 * 8) Naturschaden zu. (100ms Abklingzeit)\nSchließt Ara-Kara, Stadt der Echos in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219315] = { ["name"] = "Aggressionsablenkungsmodul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\nAnlegen: Eure Spottfähigkeiten aktivieren die brechende Energie des Moduls und schützen Euch vor 50% des erlittenen Schadens, bis zu 301603 . Dies kann nur einmal pro 1 Min. geschehen.\n\nGilt nur für Tankspezialisierungen. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[219316] = { ["name"] = "Endlose Schwarmdrüse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Stärke]\nAnlegen: Die Drüse setzt Pheromone frei, die einen endlosen Schwarm von Insekten anlocken, die Euch umkreisen. Wenn Ihr Schaden erleidet, habt Ihr eine hohe Chance auf einen Gegenschlag, der über 6 Sek. ( 2726 * 6) Naturschaden verursacht und den Euch zugefügten Schaden um 3781 reduziert.\nSchließt Ara-Kara, Stadt der Echos in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219317] = { ["name"] = "Edikt des Ernters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure Schadenszauber und -fähigkeiten haben eine Chance, eine Kugel aus instabilem Schwarzblut auf Euer Ziel zuschweben zu lassen, die beim Aufprall explodiert und ( 1 * 55918 ) Schattenschaden verursacht, die zwischen allen Gegnern in der Nähe aufgeteilt werden. Wenn Ihr die Kugel abfangt, könnt Ihr deren Macht entziehen und damit Eure Meisterschaft 15 Sek. lang um 1653 erhöhen.\nSchließt Ara-Kara, Stadt der Echos in Saison 3 von The War Within auf Schlüsselsteinstufe 12 oder höher innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[219318] = { ["name"] = "Kehlkopf des oppressiven Orators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Eure Angriffe haben eine Chance, den Kehlkopf in Bewegung zu versetzen, sodass sein finsteres Flüstern Euch beeinflusst. Jedes Flüstern durchströmt 30 Sek. lang Euren Geist und gewährt 198 Stärke.\nBenutzen: Schwenkt den Kehlkopf in der Luft, um einen quälenden Chor zu entfesseln, der Gegnern in der Nähe im Verlauf von 3 Sek. ( 1 * 58370 * 3) Schattenschaden zufügt. Euer Flüstern schließt sich dem Chor an und erhöht den Schaden, bevor er verstummt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[219319] = { ["name"] = "Doppelfangbesteck", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Beweglichkeit\nBenutzen: Öffnet den Beutel und zückt die Schattenklinge von Nx, um schnell auf Gegner vor Euch loszugehen und allen getroffenen Gegnern ( 1 * 23075 ) Schattenschaden zuzufügen.\n\nIhr könnt den Beutel bis zu zwei weitere Male innerhalb von 20 Sek. benutzen, bevor er sich selbst versiegelt und seinen Inhalt magisch auflädt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[219320] = { ["name"] = "Zähflüssiges Koaglam", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nAnlegen: Eure überschüssige Heilung lockt Schattenenergie aus der Nähe zu Eurer Gruppe, die bis zu 8407 Heilung speichert und die Gesundheit des Ziels wiederherstellt, wenn es Schaden erleidet.\nBenutzen: Kanalisiert die Kraft des Koaglmats, indem die gesamte aktuelle Schattenenergie auf Euer Ziel konzentriert wird. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[219321] = { ["name"] = "Rankendes Mixtorium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+549 Intelligenz\nAnlegen: Eure Zaubersprüche können Euch dazu inspirieren, an einem Verbündeten zu experimentieren und ihn auf unvorhergesehene Weise 20 Sek. lang zu verbessern.\nVerkaufspreis:" }
entries[219322] = { ["name"] = "Übelriechender Trank", ["text"] = "Questgegenstand\nBenutzen: Wirft den Trank auf eine ahnungslose Wache, um seine Wirksamkeit zu prüfen. (10 Sek. Abklingzeit)" }
entries[219323] = { ["name"] = "Gallertartige Salbe", ["text"] = "Questgegenstand\nBenutzen: Wirft den Trank auf eine ahnungslose Wache, um seine Wirksamkeit zu prüfen. (10 Sek. Abklingzeit)" }
entries[219324] = { ["name"] = "Brodelndes Elixier", ["text"] = "Questgegenstand\nBenutzen: Wirft den Trank auf eine ahnungslose Wache, um seine Wirksamkeit zu prüfen. (10 Sek. Abklingzeit)" }
